def _rewrite_list_item(tok: Dict[str, Any]) -> None:
    children = tok.get('children')
    if not children:
        return

    first_child = children[0]
    if first_child['type'] in ('block_text', 'paragraph'):
        text_children = first_child.get('children')
        if text_children and text_children[0]['type'] == 'raw':
            raw_text = text_children[0]['raw']
            m = TASK_LIST_ITEM.match(raw_text)
            if m:
                mark = m.group(1)
                checked = mark.lower() != '[ ]'
                text_children[0]['raw'] = raw_text[m.end():]
                tok['type'] = 'task_list_item'
                tok['attrs'] = {'checked': checked}
